def normalize_language(language: str | None) -> str:
    value = str(language or "").strip()
    aliases = {
        "es": "es-419", "es-ar": "es-419", "es-mx": "es-419",
        "en": "en-US", "pt": "pt-BR",
    }
    value = aliases.get(value.casefold(), value)
    canonical = {
        code.casefold(): code for code in SUPPORTED_LANGUAGES
    }.get(value.casefold())
    return canonical or DEFAULT_LANGUAGE


def text(key: str, language: str = DEFAULT_LANGUAGE, **values) -> str:
    selected = CATALOGS.get(normalize_language(language), CATALOGS[DEFAULT_LANGUAGE])
    template = selected.get(key, CATALOGS[DEFAULT_LANGUAGE].get(key, key))
    return template.format(**values) if values else template


def priority_label(priority: str, language: str = DEFAULT_LANGUAGE) -> str:
    """Traduce una prioridad interna y conserva valores desconocidos."""

    key = f"priority.{priority}"
    translated = text(key, language)
    return priority if translated == key else translated
